      "JavaScript": "// Helper: array → linked list\nfunction makeList(arr) {\n  let dummy = { val: 0, next: null };\n  let cur = dummy;\n  for (const v of arr) { cur.next = { val: v, next: null }; cur = cur.next; }\n  return dummy.next;\n}\n// Helper: linked list → array\nfunction listToArray(node) {\n  const res = [];\n  while (node) { res.push(node.val); node = node.next; }\n  return res;\n}\n\nfunction addTwoNumbers(l1Arr, l2Arr) {\n  let l1 = makeList(l1Arr);\n  let l2 = makeList(l2Arr);\n\n  let dummy = { val: 0, next: null };\n  let cur = dummy;\n  let carry = 0;\n\n  while (l1 || l2 || carry) {\n    const sum = (l1 ? l1.val : 0) + (l2 ? l2.val : 0) + carry;\n    carry = Math.floor(sum / 10);\n    cur.next = { val: sum % 10, next: null };\n    cur = cur.next;\n    if (l1) l1 = l1.next;\n    if (l2) l2 = l2.next;\n  }\n\n  return listToArray(dummy.next);\n}",
      "Python": "class Solution:\n    def addTwoNumbers(self, l1_arr, l2_arr):\n        # Build linked list from array\n        class ListNode:\n            def __init__(self, val=0, next=None):\n                self.val = val\n                self.next = next\n\n        def make_list(arr):\n            dummy = ListNode()\n            cur = dummy\n            for v in arr:\n                cur.next = ListNode(v)\n                cur = cur.next\n            return dummy.next\n\n        def list_to_array(node):\n            res = []\n            while node:\n                res.append(node.val)\n                node = node.next\n            return res\n\n        l1 = make_list(l1_arr)\n        l2 = make_list(l2_arr)\n\n        dummy = ListNode()\n        cur = dummy\n        carry = 0\n\n        while l1 or l2 or carry:\n            total = (l1.val if l1 else 0) + (l2.val if l2 else 0) + carry\n            carry = total // 10\n            cur.next = ListNode(total % 10)\n            cur = cur.next\n            if l1: l1 = l1.next\n            if l2: l2 = l2.next\n\n        return list_to_array(dummy.next)",
      "C++": "class Solution {\npublic:\n    // Input/output: vectors representing linked list values in order\n    vector<int> addTwoNumbers(vector<int>& l1Arr, vector<int>& l2Arr) {\n        struct ListNode {\n            int val;\n            ListNode* next;\n            ListNode(int v) : val(v), next(nullptr) {}\n        };\n\n        auto makeList = [](vector<int>& arr) -> ListNode* {\n            ListNode dummy(0);\n            ListNode* cur = &dummy;\n            for (int v : arr) { cur->next = new ListNode(v); cur = cur->next; }\n            return dummy.next;\n        };\n\n        ListNode* l1 = makeList(l1Arr);\n        ListNode* l2 = makeList(l2Arr);\n\n        ListNode dummy(0);\n        ListNode* cur = &dummy;\n        int carry = 0;\n\n        while (l1 || l2 || carry) {\n            int sum = (l1 ? l1->val : 0) + (l2 ? l2->val : 0) + carry;\n            carry = sum / 10;\n            cur->next = new ListNode(sum % 10);\n            cur = cur->next;\n            if (l1) l1 = l1->next;\n            if (l2) l2 = l2->next;\n        }\n\n        vector<int> res;\n        ListNode* node = dummy.next;\n        while (node) { res.push_back(node->val); node = node->next; }\n        return res;\n    }\n};",
      "Java": "class Solution {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int v) { val = v; }\n    }\n\n    static ListNode makeList(int[] arr) {\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (int v : arr) { cur.next = new ListNode(v); cur = cur.next; }\n        return dummy.next;\n    }\n\n    // Input/output: int arrays representing linked list values in order\n    public int[] addTwoNumbers(int[] l1Arr, int[] l2Arr) {\n        ListNode l1 = makeList(l1Arr);\n        ListNode l2 = makeList(l2Arr);\n\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        int carry = 0;\n\n        while (l1 != null || l2 != null || carry != 0) {\n            int sum = (l1 != null ? l1.val : 0) + (l2 != null ? l2.val : 0) + carry;\n            carry = sum / 10;\n            cur.next = new ListNode(sum % 10);\n            cur = cur.next;\n            if (l1 != null) l1 = l1.next;\n            if (l2 != null) l2 = l2.next;\n        }\n\n        int len = 0;\n        ListNode node = dummy.next;\n        while (node != null) { len++; node = node.next; }\n        int[] res = new int[len];\n        node = dummy.next;\n        for (int i = 0; i < len; i++) { res[i] = node.val; node = node.next; }\n        return res;\n    }\n}"
