      "JavaScript": "function productExceptSelfBasic(nums) {\n  const ans = Array(nums.length).fill(1);\n  let prefix = 1;\n  for (let i = 0; i < nums.length; i++) { ans[i] = prefix; prefix *= nums[i]; }\n  let suffix = 1;\n  for (let i = nums.length - 1; i >= 0; i--) { ans[i] *= suffix; suffix *= nums[i]; }\n  return ans;\n}",
